implementation:
#include <linux/errno.h>
#include <linux/uaccess.h>
#include <linux/slab.h>

long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret = -EINVAL;

    if (nsops == 0) {
        return -EINVAL;
    }

    sops = kmalloc_array(nsops, sizeof(*sops), GFP_KERNEL);
    if (!sops) {
        return -ENOMEM;
    }

    if (copy_from_user(sops, tsops, nsops * sizeof(*sops))) {
        goto out;
    }

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to))) {
            ret = -EFAULT;
            goto out;
        }
        ret = do_semtimedop(semid, sops, nsops, &to);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

out:
    kfree(sops);
    return ret;
}
